export type VocabWord = {
  /** Stable 1-based position in the flattened deck, for display only. */
  order: number
  cat: string
  term: string
  vi: string
  pos: string
  ex: string
  exVi: string
}

/** Flattened once at module load; every view (flashcards, browse list) filters this. */
export const VOCAB_DECK: VocabWord[] = VOCAB_DATA.flatMap(group =>
  group.items.map(([term, vi, pos, ex, exVi]) => ({ term, vi, pos, ex, exVi, cat: group.cat, order: 0 }))
).map((word, i) => ({ ...word, order: i + 1 }))

export const VOCAB_CATEGORIES: string[] = VOCAB_DATA.map(group => group.cat)
